CREATE DATABASE IF NOT EXISTS formaflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE formaflow;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','docente','corsista') NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE teacher_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,bio TEXT NULL,total_assigned_hours DECIMAL(6,2) DEFAULT 0,total_completed_hours DECIMAL(6,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE student_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,phone VARCHAR(30),birth_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,start_date DATE,end_date DATE,status ENUM('draft','active','completed','cancelled') DEFAULT 'draft',teacher_id BIGINT UNSIGNED NULL,total_hours DECIMAL(6,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE lessons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,lesson_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,status ENUM('scheduled','completed','cancelled') DEFAULT 'scheduled',google_meet_link VARCHAR(255) NULL,reminder_2d_sent TINYINT(1) DEFAULT 0,reminder_1d_sent TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('active','completed','withdrawn') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_enroll (course_id,student_id),FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lesson_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('present','absent','late') DEFAULT 'present',checkin_at DATETIME NULL,via_qr TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_att (lesson_id,student_id),FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE materials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,uploader_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,file_path VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY (uploader_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE quizzes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,published TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE quiz_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id BIGINT UNSIGNED NOT NULL,question_text TEXT NOT NULL,option_a VARCHAR(255),option_b VARCHAR(255),option_c VARCHAR(255),option_d VARCHAR(255),correct_option CHAR(1) NOT NULL,FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,score DECIMAL(5,2) DEFAULT 0,completed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE,FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,certificate_code VARCHAR(80) NOT NULL UNIQUE,pdf_path VARCHAR(255) NOT NULL,issued_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE email_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lesson_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,email_to VARCHAR(150) NOT NULL,subject VARCHAR(180) NOT NULL,body TEXT,status ENUM('sent','failed') NOT NULL,error_message TEXT NULL,sent_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE SET NULL,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
